  "Automatically add prompt caching breakpoints (cache_control markers) to requests made with this key, cutting input cost on repeated prompts. Applies to Anthropic and Bedrock Claude models; requests that already set their own cache_control markers are left untouched.": "自动向使用此键发出的请求添加提示缓存断点（cache_control 标记），从而减少重复提示的输入成本。适用于人类和基岩克劳德模型；已经设置自己的cache_control标记的请求保持不变。",
  "Automatically close the session after this many guardrail violations. Leave empty to never auto-close.": "在多次违反防护栏后自动关闭会话。留空则永远不会自动关闭。",
