  "Behavior can differ when keys, teams, or router settings are configured.": "Behavior 可以 differ 当密钥, 团队, 或路由器设置是已配置.",
  "Best effort throughput - no error if we're overallocating {lower} (Team/Key Limits checked at runtime).": "Best effort 吞吐量 - 否错误如果 we're overallocating {lower} (团队/密钥限制已选中于 runtime).",
  "Best practice: Use a descriptive name that indicates the server's purpose (e.g., 'GitHub_MCP', 'Email_Service'). Cannot contain spaces or hyphens; use underscores instead. Names must comply with SEP-986 and will be rejected if invalid (https://modelcontextprotocol.io/specification/2025-11-25/server/tools#tool-names).": "最佳实践：使用能说明服务器用途的名称（例如 GitHub_MCP、Email_Service）。不能包含空格或连字符，请改用下划线。名称必须符合 SEP-986，无效时会被拒绝（https://modelcontextprotocol.io/specification/2025-11-25/server/tools#tool-names）。",
  "Billable units the provider reported for this guardrail and what LiteLLM priced them at": "提供商报告的此护栏的计费单位以及 LiteLLM 的定价",
  "Binary uses the full weight for any hit. Match count uses half for one distinct matcher and full weight for two or more.": "二进制 uses 全部权重用于任何命中. 匹配数量 uses half 用于一个不同 matcher 和全部权重用于 two 或更多.",
  "Blast Radius": "界面：Blast Radius",
  "Blind-judge the auto-router on the real traffic of a key, team, or user (teams and users cover JWT-authenticated traffic): against the models they use today before switching, or against a fixed baseline after they have switched.": "根据密钥、团队或用户的真实流量（团队和用户覆盖 JWT 身份验证的流量）来盲目判断自动路由器：根据他们在切换之前使用的模型，或者根据他们切换后的固定基线。",
