  "Block for {blockScope}": "阻止 {blockScope}",
  "Block or mask content containing specific keywords or phrases. Upload custom word lists or add individual terms.": "拦截或屏蔽包含特定关键词或短语的内容。可上传自定义词表，或逐条添加。",
  "Block or mask specific sensitive terms and phrases": "阻止或屏蔽特定的敏感术语和短语",
  "Block or reframe competitor comparison and ranking intent. Detect when users ask to compare or recommend competitors (airline or generic competitor lists).": "阻止或重新构建竞争对手比较和排名意图。检测用户何时要求比较或推荐竞争对手（航空公司或通用竞争对手列表）。",
  "Block or reframe competitor comparison questions. Airline type uses major airlines (excluding your brand); generic requires manual competitor list.": "阻止或重新构建竞争对手比较问题。航空公司类型使用主要航空公司（不包括您的品牌）；通用需要手动列出竞争对手列表。",
  "Block or reframe competitor comparison questions. When enabled, airline type auto-loads competitors from IATA; generic type requires manual competitor list.": "拦截或改写竞品比较类问题。启用后，航空类型会从 IATA 自动加载竞品；通用类型需要手动填写竞品列表。",
  "Block returns an error when a forbidden tool is invoked. Rewrite strips the tool call but lets the rest of the response continue.": "拦截会在调用被禁止的工具时返回错误。改写会去掉该工具调用，但让响应的其余部分继续。",
