  "Callback {value0} deleted successfully": "回调 {value0} 删除于成功",
  "Called With": "Called 与",
  "Callers bring their own upstream token for this auth type, so LiteLLM never stores tokens. To preview tools and configure the tool allowlist, authorize against the upstream here: the token stays in this browser session only and is never saved to LiteLLM. An OAuth app configured below IS saved with the server, so internal users who authorize from the Tools page go through it.": "此认证类型由调用方自带上游令牌，因此 LiteLLM 不会存储令牌。要预览工具并配置允许列表，请在此向上游授权：令牌只留在本次浏览器会话中，不会保存到 LiteLLM。下方配置的 OAuth 应用会随服务器保存，因此内部用户从工具页授权时会走该应用。",
  "Callers request any model in the group by name; LiteLLM picks a deployment behind the scenes using the": "Callers 请求任何模型中分组由名称; LiteLLM picks 部署 behind scenes 使用",
  "Calling tool...": "调用工具...",
  "Can add and remove members, and change their roles.": "可以添加和移除成员, 和变化其角色.",
  "Can call all routes (AI APIs, Management, and read-only)": "可以 call 所有路由 (AI APIs, 管理, 和 read-只)",
  "Can call only AI API routes (chat/completions, embeddings, etc.)": "只能调用 AI API 路由（聊天/完成、嵌入等）",
  "Can call only management routes (user/team/key management)": "只能调用管理路由（用户/团队/密钥管理）",
  "Can create team keys, add members, and manage settings": "可以创建团队密钥、添加成员和管理设置",
  "Can only view their keys within organization.": "只能查看组织内的密钥。",
  "Can view team info, but not manage it": "可以查看团队信息, but 未管理它",
  "Can view/create keys for themselves within organization.": "可以在组织内为自己查看/创建密钥。",
  "Cancel": "取消",
  "Cancel Periodic Reload": "取消定期重新加载",
  "Cancel editing discount for {displayName}": "取消 {displayName} 的编辑折扣",
  "Cancel editing margin for {displayName}": "取消 editing 利润率用于 {displayName}",
  "Candidates Considered": "界面：Candidates Considered",
  "Cap spend on individual models, each with its own reset window. Enforced across every request this key makes.": "各个型号的支出上限，每个型号都有自己的重置窗口。在该密钥发出的每个请求中强制执行。",
  "Cap spend on individual models, each with its own reset window. Enforced across every request this key makes; usage is reported on the key's info page.": "各个型号的支出上限，每个型号都有自己的重置窗口。在该密钥发出的每个请求中强制执行；密钥的信息页面上会报告使用情况。",
  "Cap spend per model over its own window. A budget set on the bare model name also covers the provider-prefixed spelling of that model.": "Cap 支出每模型超过其自己的窗口. 预算设置上 bare 模型名称也 covers 提供商-prefixed spelling 的该模型.",
  "Cap this user's spend on individual models, each with its own reset window. Applies across every key the user holds.": "Cap 此 user's 支出上 individual 模型, 每个与其自己的重置窗口. Applies 跨每个密钥用户 holds.",
  "Caps which MCP servers, access groups, and tools this user may reach. Every key the user holds is limited to this set.": "该用户可以访问的 MCP 服务器、访问组和工具的上限。用户持有的每个密钥都仅限于该组。",
  "Case-sensitive phrases a user can include in their message to force a bump to the next-higher complexity tier when they aren't happy with results. They can force a stronger model, but not choose which one.": "用户可以在消息里加入这些区分大小写的短语，在对结果不满意时强制升到下一个更高的复杂度层级。他们可以强制使用更强的模型，但不能指定是哪一个。",
  "Categories (comma-separated)": "类别 (comma-separated)",
