  "Choose Machine-to-Machine (M2M) or Interactive (PKCE) so LiteLLM authenticates it the way you intend, then save. Until it is set, LiteLLM falls back to interactive per-user auth and treats a machine-to-machine credential shape conservatively.": "选择机器对机器 (M2M) 或交互式 (PKCE)，以便 LiteLLM 按您想要的方式对其进行身份验证，然后保存。在设置之前，LiteLLM 会回退到交互式每用户身份验证，并保守地处理机器到机器的凭证形状。",
  "Choose a logging callback...": "Choose 日志回调...",
  "Choose a template or select Custom to define your own": "Choose 模板或选择自定义到 define 你的自己的",
  "Choose a test source above (quick chat or a compliance dataset) and click \"Run Test\"": "选择上面的测试源（快速聊天或合规性数据集），然后单击“运行测试”",
  "Choose a tool from the left sidebar to start testing its functionality with custom inputs.": "Choose 工具从左侧 sidebar 到开始正在测试其 functionality 与自定义 inputs.",
  "Choose a vector store to test search queries against": "Choose 向量存储到测试搜索 queries 针对",
  "Choose between LiteLLM API session management (using previous_response_id) or UI-based session management (using chat history)": "Choose 之间 LiteLLM API 会话管理 (使用上一个_响应_ID) 或界面-基于会话管理 (使用对话历史)",
  "Choose how the proxy authenticates with this MCP server. M2M is for server-to-server communication using client credentials. Interactive (PKCE) is for user-facing flows that require browser-based authorization.": "选择代理如何向此 MCP 服务器认证。M2M 使用客户端凭证做服务间通信。交互式（PKCE）用于需要浏览器授权的用户流程。",
  "Choose how to apply the margin: percentage-based or fixed amount": "Choose 如何到应用利润率: 百分比-基于或已修复金额",
  "Choose one or more guardrails from the left sidebar to start testing and comparing results.": "Choose 一个或更多护栏从左侧 sidebar 到开始正在测试和 comparing 结果.",
  "Choose pattern type": "Choose 模式类型",
  "Choose the provider and optionally provide a name and description for your vector store.": "选择提供商，并可选择提供矢量商店的名称和描述。",
