  "Compare up to 3 models at a time": "对比正常到 3 模型于时间",
  "Compared against": "Compared 针对",
  "Compares your actual routed spend with the estimated cost of using only the most expensive model configured in the auto-router. It accounts for both the cache savings from staying on one model and the added cache costs from switching models. Savings are net of recorded LLM classification cost, which is included in actual spend. Classification cost per 1K turns is averaged over all auto-router turns, including those that skip classification. The range counts whole sessions that overlap it, so totals can differ slightly from the Overall tab, which buckets savings by UTC day.": "把你实际路由后的支出，和自动路由器里只使用最贵模型的估算费用做比较。它同时计入停在同一模型上的缓存节省，以及切换模型带来的额外缓存成本。节省额已扣除记录在案的 LLM 分类费用，该费用包含在实际支出中。每 1K 轮的分类费用是对全部自动路由器轮次取平均，包括跳过分类的轮次。时间范围按与之重叠的完整会话计数，因此合计可能与「总览」页略有不同，后者按 UTC 日汇总节省额。",
  "Comparison only. This source request was not appended to the classifier input.": "Comparison 只. 此来源请求曾是未 appended 到分类器输入.",
