  "Headers always sent to the backend agent, regardless of the client request. Admin-configured, static wins on conflict.": "无论客户端请求如何，标头始终发送到后端代理。管理员配置的静态冲突胜出。",
  "Headroom API base": "净空 API 基础",
  "Headroom is a native LiteLLM guardrail that compresses your prompts before they reach the model, so you pay for fewer input tokens. The tokens it removes are priced and shown on the Usage tab as compression savings.": "Headroom 是 LiteLLM 内置护栏，会在提示词到达模型之前压缩它们，从而减少输入 token 费用。被移除的 token 会计价，并在用量页显示为压缩节省。",
