  "High Risk": "高 Risk",
  "Higher quality weight favors more capable (pricier) models; higher cost weight favors cheaper models when the bandit has feedback to act on. Recommended: 30% quality / 70% cost split.": "更高质量的重量有利于能力更强（价格更高）的车型；当强盗有反馈可以采取行动时，较高的成本重量有利于更便宜的模型。建议：30% 质量/70% 成本分摊。",
  "Hit rate": "命中费率",
  "Holding the tier keeps an agent on one model for a whole tool loop and cuts scoring cost. A turn the router cannot match to a held decision, such as one with no session id or an expired one, is scored again": "保持该等级可以使代理在整个工具循环中保持在一个模型上，并降低评分成本。路由器无法与保留的决策匹配的回合，例如没有会话 ID 或过期的决策，将再次计分",
  "Host URL": "主机网址",
  "Hostname or IP of your Valkey server, without redis:// or a port (e.g. my-valkey.example.com)": "Hostname 或 IP 的你的 Valkey 服务器, 无需 Redis:// 或端口 (e.g. my-valkey.示例.com)",
  "Hours must be a whole number between 1 and 168": "小时数必须是 1 到 168 之间的整数",
  "Hover a bar to see the error classes behind that code.": "Hover bar 到查看错误 classes behind 该代码.",
  "How Adaptive Routing Works": "自适应路由的工作原理",
  "How Classification Works": "如何分类 Works",
  "How LiteLLM transforms your request for the specified provider.": "如何 LiteLLM transforms 你的请求用于 specified 提供商.",
  "How Toolsets Work": "如何 Toolsets Work",
  "How can I help you today?": "今天我能为您提供什么帮助？",
  "How far back to look, in tool calls. Never below the repeat count, since that could never be reached.": "在工具调用中可以回顾多远。永远不要低于重复计数，因为永远无法达到该值。",
  "How frequently the team's budget resets.": "如何 frequently team's 预算 resets.",
  "How is this calculated?": "如何是此 calculated?",
  "How it works": "它是如何运作的",
  "How long a pin survives idle (seconds)": "如何 long pin survives 空闲 (秒)",
  "How long the classifier call has before it fails and the fallback below takes over.": "如何 long 分类器 call has 之前它 fails 和回退以下 takes 超过.",
  "How long to cache each user's OAuth access token in Redis before evicting it (never longer than the token's own expires_in). Leave blank to derive the TTL from the token's expires_in, or fall back to the 12-hour default.": "在从 Redis 中清除每个用户的 OAuth 访问令牌之前缓存多久（不会超过令牌自身的 expires_in）。留空则根据令牌的 expires_in 推算 TTL，否则回退到 12 小时默认值。",
  "How many identical or failing calls count as stuck. At least 2; lower reacts sooner and misfires more.": "多少次相同或失败的调用算作卡住。至少为 2；数值越低反应越快，也更容易误判。",
  "How much this criterion counts toward the final score. All weights must add up to 100%.": "如何 much 此 criterion counts toward final 分数. 所有权重必须添加正常到 100%.",
  "How often the budget should reset": "如何 often 预算应当重置",
  "How often the budget should reset. For example, setting 'daily' will reset the budget every 24 hours": "如何 often 预算应当重置. 用于示例, 设置 'daily' 将重置预算每个 24 小时",
  "How often the group's spend resets. Leave empty for a budget that never resets": "群组支出重置的频率。为永不重置的预算留空",
  "How often the key should be automatically rotated. Choose the interval that best fits your security requirements.": "密钥自动轮换的频率。请选择最符合安全要求的间隔。",
  "How often this member's budget resets within the team. Leave unset and the budget never resets.": "如何 often 此 member's 预算 resets 之内团队. 离开 unset 和预算从不 resets.",
