  "If enabled, shows the Projects feature in the UI sidebar and the project field in key management.": "如果已启用, shows 项目功能中界面 sidebar 和项目字段中密钥管理.",
  "If enabled, the user search endpoint restricts results by organization. When off, any authenticated user can search all users.": "如果已启用, 用户搜索端点 restricts 结果由组织. 当关闭, 任何 authenticated 用户可以搜索所有用户.",
