  "Issuer (optional)": "发行人（可选）",
  "It learns from how each conversation actually goes: does the user have to rephrase or correct the model, does it get stuck repeating itself, does it run out of tool calls, does the user seem satisfied. Combined with cost, this live feedback shifts future routing toward the models that are actually working well, and improves as more conversations come in. Until there's enough feedback, it defaults to the classified tier's model.": "它会根据每段对话的实际过程来学习：用户是否需要改写或纠正模型、模型是否卡在重复输出、工具调用是否用尽、用户看起来是否满意。结合费用，这些实时反馈会把之后的路由偏向真正好用的模型，并随着对话增多而改进。在反馈足够之前，它会使用已分类层级对应的模型。",
  "JSON Preview": "JSON 预览",
  "JSON metadata for the vector store": "JSON 元数据用于向量存储",
  "JSON metadata for the vector store (optional)": "JSON 元数据用于向量存储 (可选)",
  "JSON object forwarded to the guardrail as request_data['metadata']. Custom guardrails can read per-request configuration from it.": "JSON 对象 forwarded 到护栏作为请求_数据['metadata']. 自定义护栏可以 read 每-请求配置从它.",
  "JSON object merged into litellm_params. e.g. forward_api_key, headers, model, unreachable_fallback": "JSON 对象合并到 litellm_params 中。例如forward_api_key、标头、模型、unreachable_fallback",
  "JSON object of key-value rules checked against the OAuth token response before storing. Supports dot-notation for nested fields (e.g. {\"organization\": \"my-org\", \"team.id\": \"123\"}). Tokens that fail validation are rejected with HTTP 403.": "在存储前用来校验 OAuth 令牌响应的键值规则 JSON。嵌套字段支持点号，例如 organization 与 team.id。校验失败的令牌会以 HTTP 403 拒绝。",
  "JSON object with additional information about this key. Used for tracking or custom logic": "包含有关此密钥的附加信息的 JSON 对象。用于跟踪或自定义逻辑",
  "JWT field name that contains team/group information. Use dot notation to access nested fields.": "JWT 字段名称该包含团队/分组信息. 使用 dot notation 到访问 nested 字段.",
