  "Leave empty to follow the tiers. A model chosen here is pinned: it stays the default however the tiers change.": "离开空到 follow 层级. 模型 chosen 这里是已固定: 它 stays 默认 however 层级变化.",
  "Leave empty to grant no models directly. The team keeps any models granted through its access groups": "离开空到 grant 否模型 directly. 团队 keeps 任何模型已授予透传其访问分组",
