  "Leave empty — all team models accessible to every member": "离开空 — 所有团队模型 accessible 到每个成员",
  "Left untouched, it tracks the Simple to Medium boundary, currently {value0}.": "左侧 untouched, 它 tracks 简单到中等 boundary, currently {value0}.",
  "Left untouched, it tracks the Simple to Medium boundary.": "左侧 untouched, 它 tracks 简单到中等 boundary.",
  "Legacy (uncalibrated)": "旧版 (uncalibrated)",
  "Let the classifier read the assistant's replies, so difficulty the model stated rather than the user stays visible: a plan the assistant calls complex, approved with \"yes\", is classified on the work being approved. Context Window Size then counts the last N turns across both roles rather than the last N user turns.": "让分类器读取助手的回复，这样模型给出的难度判断会保留下来，而不是只看到用户说了什么：助手称为复杂、并以「是」批准的计划，会按被批准的工作来分类。此时上下文窗口大小统计的是双方最近 N 轮，而不是最近 N 条用户消息。",
  "Let us pick models for each complexity tier.": "Let us pick 模型用于每个 complexity 层级.",
  "Lets OAuth-only clients like Claude Desktop register and sign in through the gateway. Turn off to relay the upstream server's own OAuth metadata instead (for clients pre-registered with the upstream IdP).": "允许仅支持 OAuth 的客户端（如 Claude Desktop）通过网关注册并登录。关闭后改为转发上游服务器自己的 OAuth 元数据（适用于已在上游身份提供商预注册的客户端）。",
