  "Note the corpus ID from the Vertex AI console (now labeled \"RAG Engine\" in Google Cloud)": "从 Vertex AI 控制台记下语料库 ID（在 Google Cloud 中现称为 RAG Engine）。",
  "Note: Google Cloud has renamed this to \"Agent Search\" in its console — the steps below still apply.": "注意: Google 云 has renamed 此到 \"智能体搜索\" 中其 console — 步骤以下仍然应用.",
  "Note: Google Cloud has renamed this to \"RAG Engine\" in its console — the steps below still apply.": "注意: Google 云 has renamed 此到 \"RAG Engine\" 中其 console — 步骤以下仍然应用.",
  "Note: Only pages accessible to internal user roles are shown here. Admin-only pages are excluded as they cannot be made visible to internal users regardless of this setting.": "注意：此处仅显示内部用户角色可访问的页面。仅限管理的页面被排除在外，因为无论此设置如何，内部用户都无法看到它们。",
  "Note: Sensitive headers are not shown.": "注意：不显示敏感标头。",
  "Note: This will only affect new requests after the configuration change.": "注意: 此将只 affect 新建请求之后配置变化.",
  "Number of Retries: {value0}": "重试次数：{value0}",
  "Number of models to show": "显示模型数量",
  "Number of prior user turns (tool output and harness reminders excluded) sent to the classifier as context, so a referring follow-up like \"now do the same for the streaming path\" is classified against what it refers to. Set to 0 to send only the current message.": "作为上下文发给分类器的先前用户轮次数（不含工具输出和框架提醒），这样「现在对流式路径做同样的事」这类指代后续句会按它所指向的内容分类。设为 0 则只发送当前消息。",
  "Number of top keys to show": "号码的顶部密钥到显示",
  "Number of users by successful request frequency": "号码的用户由 successful 请求 frequency",
  "OAuth 2.0 authorization server issuer (RFC 8414). Leave empty to discover endpoints from the upstream resource; set it to pin the trust anchor, which makes this issuer's document the only endpoint source (RFC 8414 §3.3), overriding the Authorization/Token/Registration URLs above and failing closed if its metadata cannot be fetched.": "OAuth 2.0 授权服务器签发方（RFC 8414）。留空则从上游资源发现端点；填写后会固定信任锚，使该签发方文档成为唯一端点来源（RFC 8414 §3.3），并覆盖上方的授权、令牌和注册 URL。若无法获取其元数据，将失败关闭。",
