  "Only DB models can be edited. You must be an admin or the creator of the model to edit it.": "只 DB 模型可以 edited. 你必须管理员或创建者的模型到编辑它.",
  "Only accept this agent being invoked with a trace-id (e.g. when used as a sub-agent).": "仅接受使用跟踪 ID 调用此代理（例如，当用作子代理时）。",
  "Only capabilities LiteLLM can faithfully proxy today are listed. Others (push notifications, extensions) are coming soon.": "目前仅列出了 LiteLLM 能够忠实代理的功能。其他功能（推送通知、扩展）即将推出。",
  "Only checked tools will be available for users to invoke. Unchecked tools will be blocked from execution.": "只已选中工具将可用用于用户到 invoke. 未勾选工具将已阻止从 execution.",
  "Only keys for this team will be able to call this model.": "只密钥用于此团队将 able 到 call 此模型.",
  "Only letters, digits, underscores, and hyphens are allowed (no spaces).": "只 letters, digits, underscores, 和 hyphens 是允许的 (否 spaces).",
  "Only on models": "只上模型",
  "Only premium users can configure UI access control": "仅高级用户可以配置界面访问控制",
  "Only proxy admins can set allowed pass through routes": "只代理 admins 可以设置允许的通过透传路由",
  "Only the API key is rotated here. Models that authenticate with an Azure AD token, AWS credentials, or a Vertex service-account JSON aren't supported yet; update those from the model's LiteLLM Params for now.": "这里只轮换 API 密钥。使用 Azure AD 令牌、AWS 凭证或 Vertex 服务账号 JSON 认证的模型尚不支持；请暂时在模型的 LiteLLM 参数中更新。",
  "Only use this model + credential combination for this team. Useful when teams want to onboard their own OpenAI keys.": "只使用此模型 + 凭证 combination 用于此团队. Useful 当团队要到 onboard 其自己的 OpenAI 密钥.",
  "Only {value0} requests will be routed to this endpoint": "只 {value0} 请求将 routed 到此端点",
