  "Optional TLS and token caching settings.": "可选 TLS 和令牌 caching 设置.",
  "Optional client certificate for mTLS.": "mTLS 的可选客户端证书。",
  "Optional columns:": "可选列：",
  "Optional cost tracking for this endpoint": "可选费用 tracking 用于此端点",
  "Optional defaults applied when members join this team. All fields can be overridden per member.": "可选 defaults applied 当成员 join 此团队. 所有字段可以 overridden 每成员.",
  "Optional description": "可选描述",
  "Optional end of the PTU window (exclusive). Leave blank for open-ended.": "可选 end 的 PTU 窗口 (exclusive). 离开空白用于打开-ended.",
  "Optional link shown to users to help them find their API key": "向用户显示的可选链接，以帮助他们找到 API 密钥",
  "Optional litellm params used for making a litellm.completion() call.": "用于进行 litellm.completion() 调用的可选 litellm 参数。",
  "Optional litellm params used for making a litellm.completion() call. Some params are automatically added by LiteLLM.": "可选 LiteLLM params 已用用于 making LiteLLM.补全() call. 一些 params 是 automatically 已添加由 LiteLLM.",
  "Optional model info params. Returned when calling `/model/info` endpoint.": "可选模型信息 params. Returned 当 calling `/模型/信息` 端点.",
  "Optional override for the authorization endpoint.": "可选覆盖用于授权端点.",
  "Optional override for the dynamic client registration endpoint.": "可选覆盖用于动态客户端 registration 端点.",
  "Optional override for the token endpoint.": "令牌端点的可选覆盖。",
  "Optional scopes requested during token exchange. Separate multiple scopes with enter or commas.": "可选范围 requested 期间令牌 exchange. Separate multiple 范围与输入或 commas.",
  "Optional scopes to request during the token exchange.": "令牌交换期间请求的可选范围。",
  "Optional scopes to request with the client_credentials grant.": "可选范围到请求与客户端_凭证 grant.",
  "Optional structured metadata — must be valid JSON if provided.": "可选的结构化元数据 — 如果提供，则必须是有效的 JSON。",
  "Optional system instructions for the model": "可选系统 instructions 用于模型",
  "Optional. IAM role ARN to assume via STS before signing. If set, LiteLLM calls sts:AssumeRole to get temporary credentials.": "可选。签名前通过 STS 扮演的 IAM 角色 ARN。设置后，LiteLLM 会调用 sts:AssumeRole 获取临时凭证。",
  "Optional. IAM role ARN to assume via STS before signing. If set, LiteLLM calls sts:AssumeRole to get temporary credentials. Uses ambient credentials (IAM role, env vars) as the source identity unless explicit keys are also provided.": "可选。签名前通过 STS 承担的 IAM 角色 ARN。如果设置，LiteLLM 会调用 sts:AssumeRole 来获取临时凭证。使用环境凭证（IAM 角色、环境变量）作为源身份，除非还提供了显式密钥。",
  "Optional. If not provided, falls back to the boto3 credential chain (IAM role, env vars, etc.).": "可选。如果未提供，则回退到 boto3 凭证链（IAM 角色、环境变量等）。",
  "Optional. If set, new members can only access these models by default. Must be a subset of the team's models above. Leave empty to give all members access to all team models.": "可选. 如果设置, 新建成员可以只访问这些模型由默认. 必须 subset 的 team's 模型以上. 离开空到 give 所有成员访问到所有团队模型.",
  "Optional. Only needed for temporary STS credentials.": "可选。仅需要临时 STS 凭证。",
  "Optional. Required if AWS Access Key ID is provided.": "可选. 必填如果 AWS 访问密钥 ID 是 provided.",
  "Optional. Session name for the AssumeRole call — appears in CloudTrail logs. Auto-generated if omitted.": "可选。 AssumeRole 调用的会话名称 — 显示在 CloudTrail 日志中。如果省略则自动生成。",
  "Optional: Add terms to the built-in list to improve classification accuracy on the technical dimension. (e.g., udp, kafka, terraform).": "可选：向内置列表添加术语，以提高技术维度的分类准确度（例如 udp、kafka、terraform）。",
  "Optional: Describe what this vector store contains": "可选: 描述什么此向量存储包含",
  "Optional: Enter custom proxy URL (e.g., http://localhost:5000)": "可选: 输入自定义代理 URL (e.g., HTTP://localhost:5000)",
  "Optional: Give your vector store a meaningful name": "可选: Give 你的向量存储 meaningful 名称",
  "Optional: Track costs for requests to this endpoint": "可选: Track costs 用于请求到此端点",
  "Optional: route requests containing specific keywords directly to a tier, e.g. route \"invoice, refund, billing\" to the medium tier.": "可选: 路由请求 containing 特定关键词 directly 到层级, e.g. 路由 \"发票, refund, 计费\" 到中等层级.",
  "Optional: when a user message contains one of these phrases, the request is bumped one tier higher than it would otherwise route to. Matching is case-sensitive, so \"LITELLM ESCALATE\" only fires on the exact, shouted form. Leave empty to disable.": "可选：当用户消息包含这些短语之一时，请求会比原本的路由再升高一个层级。匹配区分大小写，因此只有完全一致的大写形式 LITELLM ESCALATE 才会触发。留空则禁用。",
  "Optionally assign this agent to a team. The agent and its key will belong to the selected team.": "（可选）将此代理分配给一个团队。代理及其密钥将属于所选团队。",
  "Optionally select API provider credentials for this vector store eg. Bedrock API KEY": "Optionally 选择 API 提供商凭证用于此向量存储例如. Bedrock API 密钥",
  "Optionally specify which fields to check. If left empty, the entire request/response is sent to the guardrail.": "Optionally specify 哪个字段到检查. 如果左侧空, entire 请求/响应是 sent 到护栏.",
