  "Rename a tier to use your own vocabulary in the dashboard and your spend logs. Renaming doesn't change how requests are classified, and callers never see these names.": "重命名层以在仪表板和支出日志中使用您自己的词汇。重命名不会改变请求的分类方式，调用者永远不会看到这些名称。",
