  "Repeats before escalating": "升级前重复",
  "RepelloAI Argus scans prompts and responses against policies configured per asset in the Repello dashboard.": "RepelloAI Argus 会按 Repello 控制台中为每个资产配置的策略扫描提示词和响应。",
  "Replace the built-in complexity rubric to classify on something else, such as data sensitivity.": "替换内置复杂度标准，改为按其他维度分类，例如数据敏感度。",
  "Replace the built-in guardrail with custom evaluation code": "用自定义评估代码替换内置护栏",
  "Replaces a routed model that cannot take image input with the nearest higher tier that can, then the default model, instead of failing with a provider 400. Only models explicitly declared supports_vision false are replaced, and a kept session pin still wins unless you turn on the override below.": "将无法接受图像输入的路由模型替换为可以接受图像输入的最近的较高层，然后是默认模型，而不是因提供程序 400 而失败。只有明确声明supports_vision false 的模型才会被替换，并且保留的会话 pin 仍然会获胜，除非您打开下面的覆盖。",
