  "Test Connection sends a minimal request to every configured tier, classifier, default, and embedding model. The classifier probe includes its reasoning effort override.": "测试连接 sends minimal 请求到每个已配置层级, 分类器, 默认, 和嵌入模型. 分类器 probe includes 其推理 effort 覆盖.",
