  "Test model=": "测试模型=",
  "Test policy versions on production traffic without blocking requests. Shadow testing helps validate changes before full rollout.": "在生产流量上测试策略版本，且不拦截请求。影子测试有助于在正式发布前验证更改。",
  "Test query:": "测试查询:",
  "Test with": "测试用",
  "Test your search tool": "测试您的搜索工具",
  "Test your vector store by entering a search query below": "测试你的向量存储由 entering 搜索查询以下",
  "Test {value0} and compare results": "测试{value0}并比较结果",
