  "Unified guardrails only: omit role: system from guardrail evaluation input (OpenAI chat + Anthropic messages). The model still receives full messages. Use global default follows litellm_settings.skip_system_message_in_guardrail.": "仅统一护栏：省略角色：来自护栏评估输入的系统（OpenAI 聊天 + Anthropic 消息）。该模型仍然会收到完整的消息。使用全局默认值，遵循 litellm_settings.skip_system_message_in_guardrail。",
  "Unified guardrails only: omit role: tool from guardrail evaluation input (OpenAI chat + Anthropic messages). The model still receives full messages. Use global default follows litellm_settings.skip_tool_message_in_guardrail.": "Unified 护栏只: omit 角色: 工具从护栏评估输入 (OpenAI 对话 + Anthropic 消息). 模型仍然 receives 全部消息. 使用全局默认 follows LiteLLM_设置.跳过_工具_消息_中_护栏.",
  "Unified guardrails: omit role: system from guardrail input (LLM still gets full messages). Use global default follows litellm_settings.skip_system_message_in_guardrail.": "统一护栏：省略角色：来自护栏输入的系统（LLM 仍然获取完整消息）。使用全局默认值，遵循 litellm_settings.skip_system_message_in_guardrail。",
