  "Use this curl command to test the semantic filter with your current configuration.": "使用此 curl 命令到测试 semantic 筛选与你的当前配置.",
  "Use this name as the model in API calls — LiteLLM routes the request to one of the group's models.": "使用此名称作为模型中 API 调用 — LiteLLM 路由请求到一个的 group's 模型.",
  "Use tools directly from Cursor IDE with LiteLLM MCP. Enable your AI assistant to perform real-world tasks without leaving your coding environment.": "在 Cursor IDE 中通过 LiteLLM MCP 直接使用工具。让 AI 助手无需离开编码环境就能完成实际任务。",
  "Use tools directly from any MCP client with LiteLLM MCP. Enable your AI assistant to perform real-world tasks through a simple, secure connection.": "使用工具 directly 从任何 MCP 客户端与 LiteLLM MCP. 启用你的 AI 助手到 perform 真实-world tasks 透传简单, secure 连接.",
