  "With Version": "与版本",
  "With subpaths:": "使用子路径：",
  "Word Policy": "Word 策略",
  "Workflow run details": "工作流运行详情",
  "Write me a poem": "界面：Write me a poem",
  "YYYY-MM-DD HH:mm:ss": "界面：YYYY-MM-DD HH:mm:ss",
  "Year to date": "年到日期",
  "Yes": "是",
  "Yes — exclude from guardrail scan": "是 — exclude 从护栏 scan",
  "Yes, Clear": "是, 清除",
  "You are a helpful assistant...": "你是 helpful 助手...",
  "You can also mix both:": "您也可以混合两者：",
  "You can no longer create teams in this organization": "您无法再在此组织中创建团队",
  "You can only create teams within this organization": "你可以只创建团队之内此组织",
  "You can use tags to restrict the usage of certain LLMs based on tags passed in the request. Read more about tag routing": "您可以使用标签根据请求中传递的标签来限制某些 LLM 的使用。阅读有关标签路由的更多信息",
  "You can use vector stores to store and retrieve LLM embeddings.": "你可以使用向量 stores 到存储和 retrieve LLM 嵌入.",
  "You cannot view the information of a dynamically generated spend tag": "你无法查看信息的 dynamically generated 支出标签",
  "You changed the upstream URL or endpoints; the OAuth app entered here was registered for the previous upstream and may not be valid. Update the client ID, or clear it to use dynamic client registration.": "你更改了上游 URL 或端点。这里填写的 OAuth 应用是为之前的上游注册的，可能已失效。请更新客户端 ID，或清空它以使用动态客户端注册。",
  "You do not have access to budgets": "您无权访问预算",
  "You have already created a search index and loaded your documents and their embeddings into it. Enter that index name as the Vector Store ID": "你 have 已经创建于搜索索引和 loaded 你的文档和其嵌入到它. 输入该索引名称作为向量存储 ID",
  "You have unsaved changes to patterns or keywords. Remember to click \"Save Changes\" at the bottom.": "你 have unsaved 更改到模式或关键词. Remember 到点击 \"保存更改\" 于底部.",
  "You know the field names your documents use for their text and their embedding. If they are not \"text\" and \"embedding\", set them below": "你 know 字段 names 你的文档使用用于其文本和其嵌入. 如果 they 是未 \"文本\" 和 \"嵌入\", 设置 them 以下",
  "You know which embedding model created those stored embeddings. That model must be added to this proxy under Models so you can pick it below. Using a different model returns wrong results": "你 know 哪个嵌入模型创建于那些 stored 嵌入. 该模型必须已添加到此代理低于模型 so 你可以 pick 它以下. 使用不同模型 returns wrong 结果",
  "You make an API call to the LiteLLM proxy with": "你 make API call 到 LiteLLM 代理与",
  "You need a SCIM token to authenticate with the SCIM API. Create one below and use it in your SCIM provider configuration.": "你 need SCIM 令牌到 authenticate 与 SCIM API. 创建一个以下和使用它中你的 SCIM 提供商配置.",
  "You need to be logged in to create a SCIM token": "你 need 到 logged 中到创建 SCIM 令牌",
  "You'll be taken to the Flow Builder to design your policy logic visually.": "你将进入流程构建器，以可视化方式设计策略逻辑。",
