  "Your browser does not support the audio element.": "您的浏览器不支持音频元素。",
  "Your classifier model reads these names, so clearer ones can sharpen its choices.": "分类器模型会读这些名称，因此更清楚的名称能让它的选择更准确。",
  "Your current IP:": "您当前的IP：",
  "Your deployment name will be saved as the public model name, and LiteLLM will use 'azure/deployment-name' internally": "你的部署名称将已保存作为公开模型名称, 和 LiteLLM 将使用 'azure/部署-name' internally",
